-- Acceptance tests for migration 29. DISPOSABLE DATABASE ONLY (name must end in _Tests).
--   sqlcmd -S localhost -E -C -b -d GameOn_Tests -i database\30-club-suite-tests.sql
SET NOCOUNT ON; SET XACT_ABORT OFF; SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON;
IF DB_NAME() NOT LIKE N'%[_]Tests' THROW 50002,'Run these tests only on a disposable *_Tests database.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.PlatformMigrations WHERE Version=29) THROW 50002,'Apply migration 29 to this test database first.',1;
DECLARE @tag nvarchar(12)=LEFT(REPLACE(CONVERT(nvarchar(36),NEWID()),'-',''),10);
DECLARE @t TABLE(Name nvarchar(200),Pass bit);
DECLARE @one TABLE(a sql_variant);
DECLARE @row TABLE(a sql_variant,b sql_variant,c sql_variant,d sql_variant,e sql_variant,f sql_variant,g sql_variant,h sql_variant);
DECLARE @ok bit,@Op int,@Own int,@Rec int,@Coach int,@P1 int,@P2 int,@V int,@Club int,@Court int,@B bigint,@k uniqueidentifier,@Top uniqueidentifier,@ref nvarchar(40);
DECLARE @Sport int=(SELECT TOP(1) SubtypeId FROM dbo.Subtypes WHERE Slug='padel');
DECLARE @Day date=CAST(DATEADD(day,2,dbo.ToBeirut(SYSUTCDATETIME())) AS date);
DECLARE @Ten datetime2(0)=dbo.FromBeirut(DATEADD(hour,10,CAST(@Day AS datetime2(0))));
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('op'+@tag+'@gameon.invalid','Op','x'); SET @Op=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('own'+@tag+'@gameon.invalid','Owner','x'); SET @Own=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('rec'+@tag+'@gameon.invalid','Reception','x'); SET @Rec=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('co'+@tag+'@gameon.invalid','Coach','x'); SET @Coach=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('p1'+@tag+'@gameon.invalid','Player One','x'); SET @P1=SCOPE_IDENTITY();
INSERT dbo.Users(Email,DisplayName,PasswordHash) VALUES('p2'+@tag+'@gameon.invalid','Player Two','x'); SET @P2=SCOPE_IDENTITY();
INSERT dbo.PaymentOperators(UserId) VALUES(@Op);
INSERT dbo.Venues(Name,Area,Address,ListingStatus) VALUES(N'Suite venue '+@tag,N'Kaslik',N'Main road','Unverified'); SET @V=SCOPE_IDENTITY();
INSERT @one EXEC dbo.CreateClub @OperatorId=@Op,@VenueId=@V,@Name=N'Suite Club',@OwnerUserId=@Own; SELECT @Club=CONVERT(int,a) FROM @one; DELETE @one;
INSERT @one EXEC dbo.SetClubStaff @ClubId=@Club,@ActorId=@Own,@UserId=@Rec,@Role='Reception'; DELETE @one;
INSERT @one EXEC dbo.SetClubStaff @ClubId=@Club,@ActorId=@Own,@UserId=@Coach,@Role='Coach'; DELETE @one;
INSERT @one EXEC dbo.SaveCourt @ClubId=@Club,@ActorId=@Own,@Name=N'Court 1',@SubtypeId=@Sport,@SlotMinutes=60,@OpenHour=8,@CloseHour=23,@BasePrice=20,@PeakPrice=30,@PeakStartHour=18,@PeakEndHour=22; SELECT @Court=CONVERT(int,a) FROM @one; DELETE @one;
-- Fund P1's wallet with $100 through the normal verified top-up path.
SET @k=NEWID(); SET @ref=N'S-'+@tag;
INSERT @row(a,b,c,d,e,f) EXEC dbo.CreateTopUp @UserId=@P1,@Key=@k,@Amount=100,@Recipient='+96171364432'; SELECT @Top=CONVERT(uniqueidentifier,a) FROM @row; DELETE @row;
INSERT @row(a,b,c,d) EXEC dbo.SubmitTopUpReference @UserId=@P1,@TopUpId=@Top,@Reference=@ref; DELETE @row;
INSERT @one EXEC dbo.ReviewTopUp @OperatorId=@Op,@TopUpId=@Top,@Decision='VERIFY',@Note=N'Seen'; DELETE @one;
-- Wallet court payment
SET @k=NEWID(); INSERT @row(a,b,c,d,e,f,g,h) EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P1,@StartsAtUtc=@Ten,@Key=@k,@PayFromWallet=1; SELECT @B=CONVERT(bigint,a) FROM @row; DELETE @row;
INSERT @row(a,b,c,d,e,f,g,h) EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P1,@StartsAtUtc=@Ten,@Key=@k,@PayFromWallet=1; DELETE @row;
INSERT @t SELECT 'Wallet court payment charged once; club balance credited',IIF((SELECT Balance FROM dbo.WalletAccounts WHERE UserId=@P1)=80 AND (SELECT Balance FROM dbo.Clubs WHERE ClubId=@Club)=20,1,0);
INSERT @one EXEC dbo.CancelCourtBooking @BookingId=@B,@UserId=@P1; DELETE @one;
INSERT @t SELECT 'Cancelling refunds the wallet and the club balance',IIF((SELECT Balance FROM dbo.WalletAccounts WHERE UserId=@P1)=100 AND (SELECT Balance FROM dbo.Clubs WHERE ClubId=@Club)=0,1,0);
SET @ok=0; SET @k=NEWID(); BEGIN TRY EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P2,@StartsAtUtc=@Ten,@Key=@k,@PayFromWallet=1; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50006,1,0); END CATCH;
INSERT @t SELECT 'Empty wallet cannot pay and nothing is booked',IIF(@ok=1 AND NOT EXISTS(SELECT 1 FROM dbo.CourtBookings WHERE CourtId=@Court AND UserId=@P2),1,0);
-- Booking approval
SET @ok=0; BEGIN TRY EXEC dbo.SetCourtApproval @CourtId=@Court,@ActorId=@Rec,@RequiresApproval=1; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50003,1,0); END CATCH;
INSERT @t VALUES('Reception cannot change booking rules',@ok);
INSERT @one EXEC dbo.SetCourtApproval @CourtId=@Court,@ActorId=@Own,@RequiresApproval=1; DELETE @one;
DECLARE @Eleven datetime2(0)=DATEADD(hour,1,@Ten),@B2 bigint;
SET @k=NEWID(); INSERT @row(a,b,c,d,e,f,g,h) EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P1,@StartsAtUtc=@Eleven,@Key=@k,@PayFromWallet=1; SELECT @B2=CONVERT(bigint,a) FROM @row; DELETE @row;
INSERT @t SELECT 'Approval court: booking is Pending and holds the slot',IIF((SELECT Status FROM dbo.CourtBookings WHERE BookingId=@B2)='Pending',1,0);
SET @ok=0; SET @k=NEWID(); BEGIN TRY EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P2,@StartsAtUtc=@Eleven,@Key=@k; END TRY BEGIN CATCH SET @ok=IIF(ERROR_NUMBER()=50004,1,0); END CATCH;
INSERT @t VALUES('Pending slot cannot be double-booked',@ok);
DECLARE @sched TABLE(CourtId int,Court nvarchar(80),SubtypeId int,LocalStart datetime2(0),LocalEnd datetime2(0),StartsAtUtc datetime2(0),IsPeak bit,ListPrice decimal(10,2),ProPct int,SlotStatus varchar(10),BookedBy nvarchar(80),BookingId bigint,BlockId bigint,BlockReason nvarchar(120));
INSERT @sched EXEC dbo.GetCourtSchedule @ClubId=@Club,@Day=@Day,@UserId=@P2,@IncludeClasses=0;
INSERT @t SELECT 'Pending slot shows as taken to other players',IIF((SELECT SlotStatus FROM @sched WHERE StartsAtUtc=@Eleven)='Booked',1,0); DELETE @sched;
INSERT @sched EXEC dbo.GetCourtSchedule @ClubId=@Club,@Day=@Day,@UserId=@Rec,@IncludeClasses=0;
INSERT @t SELECT 'Staff see it as Pending',IIF((SELECT SlotStatus FROM @sched WHERE StartsAtUtc=@Eleven)='Pending',1,0); DELETE @sched;
INSERT @one EXEC dbo.DecideCourtBooking @BookingId=@B2,@ActorId=@Rec,@Approve=0; DELETE @one;
INSERT @t SELECT 'Declined request refunds wallet and frees slot',IIF((SELECT Status FROM dbo.CourtBookings WHERE BookingId=@B2)='Declined' AND (SELECT Balance FROM dbo.WalletAccounts WHERE UserId=@P1)=100,1,0);
SET @k=NEWID(); INSERT @row(a,b,c,d,e,f,g,h) EXEC dbo.BookCourt @CourtId=@Court,@UserId=@P2,@StartsAtUtc=@Eleven,@Key=@k; SELECT @B2=CONVERT(bigint,a) FROM @row; DELETE @row;
INSERT @one EXEC dbo.DecideCourtBooking @BookingId=@B2,@ActorId=@Rec,@Approve=1; DELETE @one;
INSERT @t SELECT 'Approved request is confirmed',IIF((SELECT Status FROM dbo.CourtBookings WHERE BookingId=@B2)='Confirmed',1,0);
