INSERT @row(a,b,c,d) EXEC dbo.CheckInMember @ClubId=@Club,@ActorId=@Rec,@AccessCode=@Code; DELETE @row;
INSERT @row(a,b,c,d) EXEC dbo.CheckInMember @ClubId=@Club,@ActorId=@Rec,@AccessCode=@Code; DELETE @row;
