DECLARE @First datetime2(0)=dbo.FromBeirut(DATEADD(hour,9,CAST(DATEADD(day,1,@Day) AS datetime2(0)))),@C1 int;
INSERT @row(a,b) EXEC dbo.CreateClassSeries @ClubId=@Club,@ActorId=@Own,@Title=N'Padel drills',@SubtypeId=@Sport,@CoachUserId=@Coach,@FirstStartsAtUtc=@First,@DurationMinutes=60,@Capacity=4,@Price=10,@Weeks=1; DELETE @row;
