-- Payroll with coach commission, staff activity, payouts
INSERT @one EXEC dbo.SetStaffCommission @ClubId=@Club,@ActorId=@Own,@UserId=@Coach,@CommissionPct=20; DELETE @one;
DECLARE @Month date=DATEFROMPARTS(YEAR(SYSUTCDATETIME()),MONTH(SYSUTCDATETIME()),1);
UPDATE dbo.Classes SET StartsAt=DATEADD(minute,10,CAST(@Month AS datetime2(0))) WHERE ClassId=@C1;
