INSERT @t SELECT 'Payroll = salary + 20% of coach''s class revenue, recorded as expense',IIF((SELECT Commission FROM dbo.StaffPay WHERE ClubId=@Club AND UserId=@Coach)=2 AND EXISTS(SELECT 1 FROM dbo.ClubExpenses WHERE ClubId=@Club AND Category='Staff' AND Amount=302),1,0);
SET @ok=0; BEGIN TRY EXEC dbo.AddStaffPay @ClubId=@Club,@ActorId=@Own,@UserId=@Coach,@PeriodMonth=@Month,@Salary=300; END TRY BEGIN CATCH SET @ok=1; END CATCH;
INSERT @t VALUES('Same month cannot be paid twice',@ok);
INSERT @t SELECT 'Staff actions are logged',IIF((SELECT COUNT(DISTINCT Action) FROM dbo.StaffActivity WHERE ClubId=@Club)>=6,1,0);
SET @ok=0; BEGIN TRY EXEC dbo.RecordClubPayout @OperatorId=@Op,@ClubId=@Club,@Amount=500,@Reference=N'PAY-BIG'; END TRY BEGIN CATCH SET @ok=1; END CATCH;
INSERT @t VALUES('Cannot pay out more than the club balance',@ok);
DECLARE @Bal decimal(12,2)=(SELECT Balance FROM dbo.Clubs WHERE ClubId=@Club),@PayRef nvarchar(40)=N'PAY-'+@tag;
INSERT @one EXEC dbo.RecordClubPayout @OperatorId=@Op,@ClubId=@Club,@Amount=@Bal,@Reference=@PayRef; DELETE @one;
