SET @ok=0; BEGIN TRY EXEC dbo.RecordClubPayout @OperatorId=@Op,@ClubId=@Club,@Amount=1,@Reference=@PayRef; END TRY BEGIN CATCH SET @ok=1; END CATCH;
INSERT @t VALUES('Payout reference cannot be reused',@ok);
INSERT @t SELECT 'Club balance equals its ledger',IIF(NOT EXISTS(SELECT 1 FROM dbo.Clubs c WHERE c.Balance<>(SELECT COALESCE(SUM(Amount),0) FROM dbo.ClubLedger l WHERE l.ClubId=c.ClubId)),1,0);
INSERT @t SELECT 'Every wallet balance equals its ledger',IIF(NOT EXISTS(SELECT 1 FROM dbo.WalletAccounts a WHERE a.Balance<>(SELECT COALESCE(SUM(Amount),0) FROM dbo.WalletLedger l WHERE l.UserId=a.UserId)),1,0);
