DECLARE @media TABLE(f varchar(64),ct varchar(20));
INSERT @media EXEC dbo.GetShotMedia @ShotId=@S;
INSERT @t SELECT 'Three reports hide a shot automatically',IIF(NOT EXISTS(SELECT 1 FROM @media),1,0);
SELECT Name, CASE WHEN Pass=1 THEN 'PASS' ELSE 'FAIL' END AS Result FROM @t;
DECLARE @failed int=(SELECT COUNT(*) FROM @t WHERE Pass=0);
IF @failed>0 BEGIN DECLARE @m nvarchar(100)=CONCAT(@failed,' club suite test(s) failed.'); THROW 50099,@m,1; END;
SELECT CONCAT((SELECT COUNT(*) FROM @t),' club suite tests passed') AS Summary;
